.cover{height:100%;box-sizing:border-box;position:relative;overflow:hidden;
 background:linear-gradient(160deg,#1a1a2e 0%,#242449 55%,#0F766E 230%);
 font-family:'Poppins','Segoe UI',Arial,sans-serif;color:#fff;
 display:flex;flex-direction:column;justify-content:space-between;padding:56px 54px 44px;}
.cov-shape1{position:absolute;top:-90px;right:-90px;width:320px;height:320px;border-radius:50%;background:rgba(94,234,212,0.18);}
.cov-shape2{position:absolute;bottom:-120px;left:-80px;width:380px;height:380px;border-radius:50%;background:rgba(255,255,255,0.06);}
.cov-shape3{position:absolute;top:280px;right:60px;width:120px;height:120px;border-radius:24px;transform:rotate(18deg);background:rgba(94,234,212,0.14);}
.cov-eyebrow{font-size:17.5px;font-weight:800;letter-spacing:3px;color:#5EEAD4;text-transform:uppercase;position:relative;z-index:2;}
.cov-series{font-size:44px;font-weight:800;margin-top:6px;letter-spacing:1px;position:relative;z-index:2;}
.cov-subject{font-size:26px;font-weight:700;color:#5EEAD4;margin-top:14px;position:relative;z-index:2;}
.cov-grade{display:inline-block;margin-top:18px;background:#5EEAD4;color:#1a1a2e;font-weight:800;font-size:26px;padding:8px 22px;border-radius:30px;position:relative;z-index:2;}
.cov-footer{position:relative;z-index:2;border-top:1px solid rgba(255,255,255,0.25);padding-top:18px;}
.cov-author{font-size:17px;font-weight:700;}
.cov-inst{font-size:16.5px;color:rgba(255,255,255,0.75);margin-top:3px;}

